import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Debian/Ubuntu安装Zerotier","description":"","frontmatter":{"title":"Debian/Ubuntu安装Zerotier","author":"麻瓜【码瓜】","date":"2026-11-19"},"headers":[],"relativePath":"posts/zerotier.md","filePath":"posts/zerotier.md","lastUpdated":1795275144000}'),o={name:"posts/zerotier.md"};function r(n,e,l,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="debian-ubuntu安装zerotier" tabindex="-1">Debian/Ubuntu安装Zerotier <a class="header-anchor" href="#debian-ubuntu安装zerotier" aria-label="Permalink to &quot;Debian/Ubuntu安装Zerotier&quot;">​</a></h1><p>假设已经在Zerotier后台创建了一个名为‘abcdefg’的网络ID，Debian/Ubuntu系统的VPS可以按下述步骤加入它。</p><h2 id="安装zerotier-one" tabindex="-1">安装ZeroTier One <a class="header-anchor" href="#安装zerotier-one" aria-label="Permalink to &quot;安装ZeroTier One&quot;">​</a></h2><p>你需要先在你的Debian系统上安装ZeroTier One。可以通过以下命令来进行安装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -s https://install.zerotier.com | sudo bash</span></span></code></pre></div><h2 id="启动zerotier-one" tabindex="-1">启动ZeroTier One <a class="header-anchor" href="#启动zerotier-one" aria-label="Permalink to &quot;启动ZeroTier One&quot;">​</a></h2><p>安装完成后，启动ZeroTier One服务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl start zerotier-one</span></span></code></pre></div><h2 id="检查zerotier-one服务状态" tabindex="-1">检查ZeroTier One服务状态 <a class="header-anchor" href="#检查zerotier-one服务状态" aria-label="Permalink to &quot;检查ZeroTier One服务状态&quot;">​</a></h2><p>确保ZeroTier One服务正常运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl status zerotier-one</span></span></code></pre></div><h2 id="加入zerotier网络" tabindex="-1">加入ZeroTier网络 <a class="header-anchor" href="#加入zerotier网络" aria-label="Permalink to &quot;加入ZeroTier网络&quot;">​</a></h2><p>使用你的网络ID来加入ZeroTier网络，执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo zerotier-cli join abcdefg</span></span></code></pre></div><h2 id="检查网络连接状态" tabindex="-1">检查网络连接状态 <a class="header-anchor" href="#检查网络连接状态" aria-label="Permalink to &quot;检查网络连接状态&quot;">​</a></h2><p>确认已经成功加入网络：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo zerotier-cli listnetworks</span></span></code></pre></div><p>你应该看到类似以下的输出，表示你已经连接到网络：</p><blockquote><p>200 listnetworks</p><ul><li>abcdefg 200 join 1.2.3.4/5.6.7.8</li></ul></blockquote><h2 id="设置开机自动启动" tabindex="-1">设置开机自动启动 <a class="header-anchor" href="#设置开机自动启动" aria-label="Permalink to &quot;设置开机自动启动&quot;">​</a></h2><p>如果希望在系统启动时自动启动ZeroTier One服务，可以执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl enable zerotier-one</span></span></code></pre></div><p>这些步骤完成后，你的Debian/Ubuntu系统应该已经成功加入了ZeroTier网络ID为abcdefg的网络。接下来可以先给他手动分配一个固定的虚拟局域网IP地址，然后就可以像局域网的VPS一样，按照自己的需求进行相应的操作了。</p>',23)])])}const b=a(o,[["render",r]]);export{u as __pageData,b as default};
